export const archiveMarkup = "<div id=\"experience\">\n    <button id=\"skipPlatform\" class=\"archive-skip\" type=\"button\" data-panel=\"overview\">Skip to the platform workspace</button>\n    <div id=\"scrolltrack\" aria-hidden=\"true\"></div>\n    <div id=\"stage\" role=\"main\" aria-label=\"ResQSync response archive. Drag to rotate the photographs, or open the grid from the menu.\">\n      <div id=\"world\">\n        <div id=\"orb\"></div>\n        <h1 id=\"headline\"><span class=\"inner\">\n          <span class=\"sphere-name\">ResQ<em>Sync</em></span>\n          <span class=\"sphere-words\"><span style=\"--i:0\">Every</span> <span style=\"--i:1\">resource</span> <span style=\"--i:2\">where</span> <span style=\"--i:3\">it</span> <span style=\"--i:4\">matters.</span></span>\n          <span class=\"sphere-label\">One network. Across India.</span>\n        </span></h1>\n      </div>\n    </div>\n    <div class=\"vig\" aria-hidden=\"true\"></div>\n    <section id=\"grid\" inert aria-hidden=\"true\" aria-label=\"Response archive grid\">\n      <div class=\"gridhead\"><span>India / The response archive</span><span>01 — 21</span></div>\n      <div class=\"rows\"></div>\n      <p class=\"gridfoot\">Indian place photography and AI-generated response illustrations. Not customer deployments or live incidents.</p>\n    </section>\n    <header class=\"chrome\">\n      <a class=\"wordmark\" href=\"#\" aria-label=\"ResQSync home\">ResQ<em>Sync</em></a>\n      <div class=\"header-actions\">\n        <button class=\"platform-link\" type=\"button\" data-panel=\"overview\">Workspace <span aria-hidden=\"true\">↗</span></button>\n        <button class=\"theme-toggle\" type=\"button\" data-theme-toggle aria-label=\"Switch to light mode\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5\"/></svg><span class=\"theme-label\">Light mode</span></button>\n        <button id=\"menuBtn\" class=\"menu-btn\" type=\"button\" aria-expanded=\"false\" aria-controls=\"menu\" aria-label=\"Open menu\"><span class=\"menu-label\">Menu</span><span class=\"bars\" aria-hidden=\"true\"><i></i><i></i></span></button>\n      </div>\n    </header>\n    <aside class=\"bio chrome\">\n      <div class=\"who\"><img id=\"avatar\" alt=\"An illustrative Indian response team\" width=\"52\" height=\"52\"><div><b>One coordinated response.</b><span>Districts · State agencies · Relief networks</span></div></div>\n      <p>Track an incident, find available crews, and keep the next team informed. A shared workspace for India's response networks.</p>\n      <button class=\"bio-link\" type=\"button\" data-panel=\"overview\">Open the workspace <span aria-hidden=\"true\">↗</span></button>\n    </aside>\n    <div class=\"colophon chrome\"><span>The Response Archive 2026</span><button type=\"button\" data-panel=\"contact\">Plan your deployment <span aria-hidden=\"true\">↗</span></button></div>\n    <button id=\"gridBtn\" class=\"gridbtn\" type=\"button\" aria-label=\"Toggle grid view\" aria-pressed=\"false\"><b></b><b></b><b></b><b></b></button>\n    <div class=\"cue chrome\"><s></s><span>Drag to rotate</span></div>\n    <button id=\"motionToggle\" class=\"motion-control chrome\" type=\"button\" aria-label=\"Pause sphere rotation\" aria-pressed=\"false\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M5 3v10M11 3v10\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg></button>\n    <div id=\"menu\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Main menu\" aria-hidden=\"true\" inert>\n      <div class=\"menu-layout\">\n        <div class=\"menu-feature\">\n          <p class=\"overline\">ResQSync / India</p>\n          <h2>The response desk.</h2>\n          <p>Incidents, resources, and the people responsible for them.</p>\n          <figure><img src=\"https://images.pexels.com/photos/27869350/pexels-photo-27869350.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200\" alt=\"Boats moored on the backwaters of Kerala, India\" loading=\"lazy\"><figcaption>Kerala, India. Photograph by Karl Ahnee.</figcaption></figure>\n        </div>\n        <nav aria-label=\"Workspace navigation\">\n          <a class=\"menu-overview\" href=\"#overview\" data-panel=\"overview\"><span class=\"menu-link-name\">Open workspace</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Your overview and recent activity.</small></a>\n          <div class=\"menu-nav-group\">\n            <p>Operations</p>\n            <a href=\"#crises\" data-panel=\"crises\" aria-label=\"Crises: crisis management\"><span class=\"menu-link-name\">Crises</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Events, locations, and updates.</small></a>\n            <a href=\"#resources\" data-panel=\"resources\" aria-label=\"Resources: resource management\"><span class=\"menu-link-name\">Resources</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Inventory and assignments.</small></a>\n            <a href=\"#conflicts\" data-panel=\"conflicts\" aria-label=\"Allocations: conflict resolution\"><span class=\"menu-link-name\">Allocations</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Requests that need a decision.</small></a>\n          </div>\n          <div class=\"menu-nav-group\">\n            <p>People &amp; planning</p>\n            <a href=\"#users\" data-panel=\"users\" aria-label=\"People and access: users and roles\"><span class=\"menu-link-name\">People &amp; access</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Teams, agencies, and permissions.</small></a>\n            <a href=\"#collaboration\" data-panel=\"collaboration\" aria-label=\"Messages: communication and collaboration\"><span class=\"menu-link-name\">Messages</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Conversations, notes, and files.</small></a>\n            <a href=\"#analytics\" data-panel=\"analytics\" aria-label=\"Reports: analytics and reporting\"><span class=\"menu-link-name\">Reports</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Usage, response times, and trends.</small></a>\n            <a href=\"#decision\" data-panel=\"decision\" aria-label=\"Scenario planning: decision support\"><span class=\"menu-link-name\">Scenario planning</span><span class=\"menu-link-arrow\" aria-hidden=\"true\">↗</span><small>Compare allocation options.</small></a>\n          </div>\n        </nav>\n      </div>\n      <div class=\"menu-footer\"><p>Demo workspace. No live incidents or dispatch.</p><div class=\"menu-secondary\"><a href=\"#archive\" data-grid>Photographs</a><button type=\"button\" data-panel=\"trust\">Privacy &amp; security</button><button type=\"button\" data-panel=\"contact\">Deployment brief</button><button type=\"button\" data-panel=\"credits\">Image credits</button></div><button class=\"theme-toggle\" type=\"button\" data-theme-toggle aria-label=\"Switch to light mode\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5\"/></svg><span class=\"theme-label\">Light mode</span></button></div>\n    </div>\n    <div id=\"lit\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"litTitle\" aria-describedby=\"litNote\" aria-hidden=\"true\" inert>\n      <button class=\"scrim\" type=\"button\" data-close aria-label=\"Close field note\" tabindex=\"-1\"></button>\n      <div class=\"plate\">\n        <div class=\"shot\"><img id=\"litImage\" alt=\"\"><button type=\"button\" data-close>Close</button></div>\n        <div class=\"meta\"><div><h2 id=\"litTitle\"></h2><div class=\"where\" id=\"litWhere\"></div></div><p class=\"note\" id=\"litNote\"></p></div>\n        <div class=\"litfoot\"><a id=\"litCredit\" href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\"></a><div><button id=\"prevShot\" type=\"button\" aria-label=\"Previous field note\">←</button><span id=\"litCount\"></span><button id=\"nextShot\" type=\"button\" aria-label=\"Next field note\">→</button></div></div>\n      </div>\n    </div>\n    <div id=\"panel\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"panelTitle\" aria-hidden=\"true\" inert>\n      <button class=\"theme-toggle panel-theme\" type=\"button\" data-theme-toggle aria-label=\"Switch to light mode\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5\"/></svg><span class=\"theme-label\">Light mode</span></button>\n      <button class=\"panel-close\" type=\"button\" data-close-panel>Close <span aria-hidden=\"true\">×</span></button>\n      <div class=\"panel-content\">\n        <div class=\"panel-view\" data-view=\"platform\" hidden>\n          <div class=\"workspace-top\"><button class=\"ws-icon-btn ws-nav-toggle\" type=\"button\" data-ws-drawer aria-label=\"Open navigation\" aria-expanded=\"false\" aria-controls=\"wsSidebar\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg></button><a class=\"workspace-wordmark\" href=\"#\" data-home>ResQ<em>Sync</em></a><nav class=\"ws-breadcrumb\" aria-label=\"Breadcrumb\"><button type=\"button\" data-panel=\"overview\">Workspace</button><span aria-hidden=\"true\">/</span><span id=\"wsCrumb\" aria-current=\"page\">Overview</span></nav><div class=\"ws-top-actions\"><span class=\"ws-demo-pill\">Demo data</span><label class=\"workspace-role\"><span>View as</span><select id=\"demoRole\" aria-label=\"Preview as a different user role\"><option value=\"admin\">Admin</option><option value=\"crisis-manager\">Crisis manager</option><option value=\"resource-coordinator\">Resource coordinator</option><option value=\"viewer\">Viewer</option></select></label><button class=\"theme-toggle theme-toggle--compact\" type=\"button\" data-theme-toggle aria-label=\"Switch to light mode\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5\"/></svg><span class=\"theme-label\">Light mode</span></button><button class=\"ws-exit\" type=\"button\" data-close-panel aria-label=\"Back to site\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m15 6-6 6 6 6\"/></svg><span>Back to site</span></button></div></div>\n          <div class=\"workspace-shell\"><aside class=\"workspace-sidebar\" id=\"wsSidebar\" aria-label=\"Workspace navigation\"><nav aria-label=\"Workspace modules\"><div class=\"ws-nav-group\"><p>Operations</p><button type=\"button\" data-panel=\"overview\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z\"/></svg><span class=\"ws-nav-label\">Overview</span></button><button type=\"button\" data-panel=\"crises\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3.5 2.5 20h19L12 3.5Z\"/><path d=\"M12 10v4.5M12 17.2h.01\"/></svg><span class=\"ws-nav-label\">Crises</span><span class=\"ws-badge\" data-badge=\"crises\"></span></button><button type=\"button\" data-panel=\"resources\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3.5 7.5 12 3.5l8.5 4v9L12 20.5l-8.5-4v-9Z\"/><path d=\"M3.5 7.5 12 11.5l8.5-4M12 11.5v9\"/></svg><span class=\"ws-nav-label\">Resources</span></button><button type=\"button\" data-panel=\"conflicts\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 7h12l-3-3M20 17H8l3 3\"/></svg><span class=\"ws-nav-label\">Allocations</span><span class=\"ws-badge\" data-badge=\"conflicts\"></span></button></div><div class=\"ws-nav-group\"><p>Team</p><button type=\"button\" data-panel=\"users\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"9\" cy=\"8\" r=\"3.3\"/><path d=\"M2.8 20c.8-3.5 3.3-5.6 6.2-5.6s5.4 2.1 6.2 5.6M16 4.8a3.3 3.3 0 0 1 0 6.4M18 14.6c1.8.8 2.9 2.6 3.2 5.4\"/></svg><span class=\"ws-nav-label\">People &amp; access</span></button><button type=\"button\" data-panel=\"collaboration\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 5h16v11H9l-5 4V5Z\"/></svg><span class=\"ws-nav-label\">Messages &amp; files</span><span class=\"ws-badge\" data-badge=\"collaboration\"></span></button></div><div class=\"ws-nav-group\"><p>Insights</p><button type=\"button\" data-panel=\"analytics\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 20v-8M12 20V5M19 20v-11M3 20h18\"/></svg><span class=\"ws-nav-label\">Reports</span></button><button type=\"button\" data-panel=\"decision\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 6h9M17 6h3M4 12h3M11 12h9M4 18h11M19 18h1\"/><circle cx=\"15\" cy=\"6\" r=\"2\"/><circle cx=\"9\" cy=\"12\" r=\"2\"/><circle cx=\"17\" cy=\"18\" r=\"2\"/></svg><span class=\"ws-nav-label\">Scenario planning</span></button></div></nav><div class=\"workspace-sidebar-foot\"><p>Sample data, saved on this device. No live dispatch.</p><button type=\"button\" data-panel=\"trust\">Privacy &amp; security</button><button type=\"button\" data-reset-demo>Reset demo data</button></div></aside><div class=\"ws-scrim\" data-ws-drawer-close aria-hidden=\"true\"></div><main class=\"workspace-content\" id=\"workspaceContent\"><h2>Overview</h2></main></div>\n          <div id=\"workToast\" class=\"work-toast\" role=\"status\" aria-live=\"polite\" hidden></div>\n        </div>\n        <div class=\"panel-view\" data-view=\"trust\" hidden>\n          <p class=\"overline\">02 / Trust &amp; accountability</p>\n          <h2>Privacy, access,<br><em>and responsibility.</em></h2>\n          <p class=\"panel-lede\">This India-focused workspace is an interactive product demo, not an operational service. Applicable Indian privacy, procurement, security, and data-residency requirements must be reviewed before deployment. Cross-border requirements depend on the organization and jurisdiction.</p>\n          <div class=\"trust-notes\">\n            <article><span>01</span><div><h3>Data sovereignty</h3><p>Define hosting region, organization access, retention, and data flows for the intended Indian deployment. No residency or legal compliance commitment is implied by this browser-based preview.</p></div></article>\n            <article><span>02</span><div><h3>Authentication &amp; access</h3><p>Production requires a verified identity provider, server-side authorization, organization isolation, and monitored audit records. The demo role selector is only an interface preview and must not be used as a security control.</p></div></article>\n            <article><span>03</span><div><h3>Cross-border requirements</h3><p>FedRAMP, HIPAA, and CJIS may be relevant to specific US-facing deployments; they are not blanket Indian requirements. This concept has no FedRAMP authorization or claimed HIPAA / CJIS certification. Do not enter protected, patient, or criminal justice information.</p></div></article>\n            <article><span>04</span><div><h3>Human authority</h3><p>Recommendations support authorized decision-makers. ResQSync is not India's 112 emergency service, an official dispatch system, or a substitute for clinical or incident-command judgment. Nothing in this demo dispatches responders.</p></div></article>\n          </div>\n          <div class=\"policy-notes\"><details><summary>Privacy Policy <span>+</span></summary><p>Workspace changes, fictional user profiles, messages, and attachment metadata are stored in this browser's local storage when available. Document content stays only in the current session. Use the demo reset to restore the sample dataset. No form details or documents are sent to a ResQSync server. A deployment brief is downloaded locally only when requested. External image, video, and Google Fonts providers receive network requests and may process IP addresses and technical metadata. This is a preview notice, not an operational privacy policy; final terms require legal review.</p></details><details><summary>Terms of Service <span>+</span></summary><p>This is an illustrative concept, not an operational service or offer. It must not be used as the sole means of emergency communication or resource dispatch. Images depict Indian place context and labeled AI-generated response illustrations, not ResQSync customers. Demo incidents, organizations, scores, and allocations are fictional. Role controls are not authentication. Availability, fees, security, identity management, support, and data obligations require a signed agreement and production infrastructure before actual use.</p></details></div>\n        </div>\n        <div class=\"panel-view\" data-view=\"contact\" hidden>\n          <p class=\"overline\">03 / Plan before the next call</p>\n          <h2>Plan your<br><em>deployment.</em></h2>\n          <p class=\"panel-lede\">Tell us which teams and resources need to work together. Download a brief to take to your next planning meeting. Nothing is sent from this form.</p>\n          <form id=\"briefingForm\">\n            <div class=\"form-pair\"><label>Your name<input name=\"name\" autocomplete=\"name\" placeholder=\"Aarav Sharma\" required></label><label>Work email<input name=\"email\" type=\"email\" autocomplete=\"email\" placeholder=\"you@organization.in\" required></label></div>\n            <label>Organization<input name=\"organization\" autocomplete=\"organization\" placeholder=\"Agency or response network\" required></label>\n            <label>Your network<select name=\"network\" required><option value=\"\" disabled selected>Select your response context</option><option>Municipal Fire &amp; EMS</option><option>Trauma systems</option><option>State emergency management</option><option>Humanitarian &amp; NGOs</option><option>Multi-agency / other</option></select></label>\n            <label>Which resource conflicts do you need to solve?<textarea name=\"needs\" rows=\"3\" placeholder=\"Teams, rescue vehicles, medical supplies, regional capacity…\"></textarea></label>\n            <p class=\"form-note\">Do not include patient details, restricted information, or live incident data.</p>\n            <button type=\"submit\" class=\"briefing-submit\">Download your deployment brief <span aria-hidden=\"true\">↗</span></button>\n            <p id=\"briefingStatus\" role=\"status\" aria-live=\"polite\">A text file is prepared locally. No information is transmitted.</p>\n          </form>\n        </div>\n        <div class=\"panel-view\" data-view=\"credits\" hidden>\n          <p class=\"overline\">04 / The response archive</p>\n          <h2>The people<br><em>behind the images.</em></h2>\n          <p class=\"panel-lede\">Indian place photography from Pexels and clearly identified AI-generated response illustrations. No image is presented as a ResQSync customer deployment or endorsement.</p>\n          <div class=\"credit-list\"></div>\n          <p class=\"film-credit\">Kerala intro film: <a href=\"https://www.pexels.com/video/serene-kerala-backwaters-with-lush-greenery-29988893/\" target=\"_blank\" rel=\"noopener noreferrer\">Stijn Dijkstra / Pexels ↗</a></p>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div id=\"dot\" aria-hidden=\"true\"></div>\n  <p id=\"themeStatus\" class=\"theme-status\" role=\"status\" aria-live=\"polite\"></p>";
